import { useState, useEffect } from "react";
import "./PostList.css";

const PostList = () => {
    const [posts, setPosts] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchPosts = async () => {
        setLoading(true);
        try {
            const response = await fetch("https://jsonplaceholder.typicode.com/posts");
            const data = await response.json();
            setPosts(data.slice(0, 10)); // Lấy 10 bài viết đầu tiên
        } catch (error) {
            console.error("Lỗi khi lấy dữ liệu:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPosts();
    }, []);

    return (
        <div className="post-container">
            <h2>Danh sách bài viết</h2>
            <h3>Hiển thị 10 bài viết đầu tiên</h3>
            <button onClick={fetchPosts}>Tải lại</button>
            {loading ? <p>Đang tải...</p> : (
                <ul className="post-list">
                    {posts.map(post => (
                        <li key={post.id} className="post-item">
                            <img src={`https://via.placeholder.com/150?text=Post+${post.id}`} alt={`Bài viết ${post.id}`} className="post-image" />
                            <div className="post-content">
                                <strong>Bài viết {post.id}: {post.title}</strong>
                                <p>{post.body}</p>
                            </div>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default PostList;
